$:set -euo pipefail
api=repos/BestNameYet/Terminals/contents/workspaces/2d-state-event-procedure-design/src/iterator.mjs
previous=44ae5dd78175bc90adff9e06a86f26813f9a80f4
expected=dcfcdfd7de2eb58d1eb77633b85c32b9bd9988e7
test "$(gh api "$api?ref=main" --jq .sha)" = "$previous"
content=$(base64 -w0 <<'ITERATOR_SOURCE'
export async function iterate(steps, returnSchemas) {
  const e = Array(steps.length).fill(null)
  const keywordIndexes = new Map()

  for (let i = 0; i < steps.length; i += 1) {
    const keyword = Object.keys(returnSchemas[i])[0]
    keywordIndexes.set(keyword, i)
  }

  function read(keyword) {
    const index = keywordIndexes.get(keyword)
    const record = e[index]

    if (record?.valid === true) {
      return record.input[keyword]
    }
  }

  let i = 0
  while (i < steps.length) {
    e[i] = await steps[i](e, i, read)

    if (e[i].valid) {
      i += 1
    }
  }

  return e
}
ITERATOR_SOURCE
)
commit=$(gh api --method PUT "$api" -f branch=main -f message='Use a single procedure iterator with keyword lookup' -f sha="$previous" -f content="$content" --jq .commit.sha)
test "$(gh api "$api?ref=$commit" --jq .sha)" = "$expected"
test "$(gh api "$api?ref=main" --jq .sha)" = "$expected"
printf 'published_commit=%s\npublished_blob=%s\n' "$commit" "$expected"
